options.css:
@ .wizard-container {
    display: flex;
    justify-content: center;
}@ 
.wizard-timeline {
	content: "";
	height: 3px;
	margin-top: 35px;
	position: absolute;
	z-index: 10;
}@ 
.wizard {
	height: 145px;
	z-index: 30;
}@ 
.wizard td {
	text-align: center;
	font-size: 14px;
}@ 
.wizard td i {
	width: 50px;
	padding: 10px;
}@ 
.wizard td.text {
	text-transform: uppercase;
	white-space: pre-wrap;
	vertical-align: top;
	font-size: 12px;
}@
